#include <bits/stdc++.h>
using namespace std;

class InputReader {
public:
    std::istream& in;
    std::string buffer;
    std::istringstream st;

    InputReader(std::istream& stream) : in(stream) {}

    std::string next() {
        while (!st || !(st >> std::ws, st)) {
            if (!std::getline(in, buffer))
                return "";
            st.clear();
            st.str(buffer);
        }
        std::string token;
        st >> token;
        return token;
    }

    bool hasMoreTokens() {
        while (!st || !(st >> std::ws, st)) {
            if (!std::getline(in, buffer))
                return false;
            st.clear();
            st.str(buffer);
        }
        return true;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }
};

class G {
public:
    struct Edge {
        int u, flow, rid, cost;
        Edge(int a, int b, int c, int d) : u(a), flow(b), rid(c), cost(d) {}
    };

    class MinCostMaxFlow {
    public:
        std::vector<std::vector<Edge>> al;
        std::vector<std::vector<Edge>> ja;
        std::vector<int> d;
        int N, S, T, maxFlow, minCost;
        const int gmax = INT_MAX / 100;
        int edges = 0;

        std::vector<int> node, visit, prv, prve, dist;

        MinCostMaxFlow(int n, int source, int sink) : N(n), S(source), T(sink), maxFlow(0), minCost(0) {
            al.resize(N);
            d.resize(N);
        }

        void addEdge(int u, int v, int flow, int cost) {
            int lu = (int)al[u].size();
            int lv = (int)al[v].size();
            al[u].emplace_back(v, flow, cost, lv);
            al[v].emplace_back(u, 0, -cost, lu);
        }

        void convertToArray() {
            ja.resize(N);
            for (int i = 0; i < N; i++) {
                ja[i] = al[i];
                al[i].clear();
            }
        }

        bool BellmanFord(bool check) {
            std::fill(d.begin(), d.end(), gmax);
            d[S] = 0;
            for (int i = 0; i < N - 1; i++) {
                for (int j = 0; j < N; j++) {
                    for (auto& e : ja[j]) {
                        if (e.flow == 0) continue;
                        if (d[j] + e.cost < d[e.u]) {
                            d[e.u] = d[j] + e.cost;
                        }
                    }
                }
            }
            if (check) {
                for (int j = 0; j < N; j++) {
                    for (auto& e : ja[j]) {
                        if (e.flow == 0) continue;
                        if (d[j] + e.cost < d[e.u]) return false;
                    }
                }
            }
            return true;
        }

        bool simple() {
            node.resize(N);
            visit.resize(N);
            prv.resize(N);
            prve.resize(N);
            dist.resize(N);
            std::fill(dist.begin(), dist.end(), gmax);
            node[0] = S;
            dist[0] = 0;
            int front = 1, back = 0;
            while (front != back) {
                int u = node[back++];
                int distu = dist[u];
                if (back == N) back = 0;
                visit[u] = 2;
                for (int i = 0; i < (int)ja[u].size(); i++) {
                    auto& e = ja[u][i];
                    if (e.flow == 0) continue;
                    int cdist = distu + e.cost;
                    if (cdist < dist[e.u]) {
                        if (visit[e.u] == 0) {
                            node[front] = e.u;
                            if (++front == N) front = 0;
                        } else if (visit[e.u] == 2) {
                            if (--back == -1) back += N;
                            node[back] = e.u;
                        }
                        visit[e.u] = 1;
                        prv[e.u] = u;
                        prve[e.u] = i;
                        dist[e.u] = cdist;
                    }
                }
            }
            return visit[T] != 0;
        }

        struct pair {
            int F, S;
            pair(int a, int b) : F(a), S(b) {}
            bool operator<(const pair& other) const {
                return S > other.S; // for min-heap
            }
        };

        bool dijkstra() {
            visit.assign(N, 0);
            prv.assign(N, -1);
            prve.assign(N, -1);
            dist.assign(N, gmax);
            std::priority_queue<pair> pq;
            dist[S] = 0;
            pq.emplace(S, 0);
            while (!pq.empty()) {
                auto p = pq.top(); pq.pop();
                if (dist[p.F] < p.S) continue;
                visit[p.F] = 2;
                for (int i = 0; i < (int)ja[p.F].size(); i++) {
                    auto& e = ja[p.F][i];
                    if (e.flow == 0) continue;
                    int cdist = p.S + e.cost + d[p.F] - d[e.u];
                    if (cdist < dist[e.u]) {
                        if (visit[e.u] == 2) return false;
                        dist[e.u] = cdist;
                        prv[e.u] = p.F;
                        prve[e.u] = i;
                        visit[e.u] = 1;
                        pq.emplace(e.u, cdist);
                    }
                }
            }
            return visit[T] != 0;
        }

        int augment() {
            int p = T;
            int minFlow = gmax;
            while (p != S) {
                int pp = prv[p], pe = prve[p];
                minFlow = std::min(minFlow, ja[pp][pe].flow);
                p = pp;
            }
            p = T;
            while (p != S) {
                int pp = prv[p], pe = prve[p];
                ja[pp][pe].flow -= minFlow;
                ja[p][ja[pp][pe].rid].flow += minFlow;
                p = pp;
            }
            maxFlow += minFlow;
            return minFlow;
        }

        bool calSimple() {
            while (simple()) {
                minCost += dist[T] * augment();
            }
            return true;
        }

        void updPotential() {
            for (int i = 0; i < N; i++) {
                if (visit[i] != 0) {
                    d[i] += dist[i] - dist[S];
                }
            }
        }

        bool calWithPotential() {
            // Uncomment to check for negative cycles
            // if (!BellmanFord(false)) return false;
            while (dijkstra()) {
                int minVal = dist[T] + d[T] - d[S];
                minCost += minVal * augment();
                updPotential();
            }
            return true;
        }
    };

    int n, m, k, c, d;
    std::vector<int> a, f;

    void solve(int testNumber, InputReader& in, std::ostream& out) {
        n = in.nextInt();
        m = in.nextInt();
        k = in.nextInt();
        c = in.nextInt();
        d = in.nextInt();

        int maxl = n + k;
        int T = n * maxl + 1;
        MinCostMaxFlow ans(T + 1, 0, T);

        a.resize(k + 1);
        f.resize(n + 1);
        for (int i = 1; i <= k; i++) {
            a[i] = in.nextInt();
            f[a[i]]++;
        }

        for (int i = 1; i <= n; i++) {
            if (f[i] == 0) continue;
            ans.addEdge(0, i, f[i], 0);
        }

        for (int i = 2; i <= n; i++) {
            for (int l = 0; l < maxl - 1; l++) {
                ans.addEdge(l * n + i, (l + 1) * n + i, k, c);
            }
        }

        for (int i = 1; i <= m; i++) {
            int a_ = in.nextInt(), b_ = in.nextInt();
            for (int l = 0; l < maxl - 1; l++) {
                for (int p = 1; p <= k; p++) {
                    if (a_ != 1)
                        ans.addEdge(n * l + a_, n * (l + 1) + b_, 1, d * (2 * p - 1) + c);
                    if (b_ != 1)
                        ans.addEdge(n * l + b_, n * (l + 1) + a_, 1, d * (2 * p - 1) + c);
                }
            }
        }

        for (int l = 1; l < maxl; l++) {
            ans.addEdge(l * n + 1, T, k, 0);
        }

        ans.convertToArray();
        // ans.calWithPotential();
        ans.calSimple();

        if (ans.maxFlow != k) {
            out << "BUG\n";
        } else {
            out << ans.minCost << "\n";
        }
    }
};

int main() {
    G solver;
    InputReader in(std::cin);
    solver.solve(1, in, std::cout);
    return 0;
}

